def windows():
    """float32 array, COUNT x 1536: each a window of 16 embeddings,
    flattened. numpy is imported here, not at the top, so importing this
    module never fails where numpy is missing."""
    import numpy as np
    q = np.frombuffer(base64.b64decode("".join(EMBEDDINGS)), dtype=np.int8)
    emb = q.reshape(-1, 96).astype(np.float32) * np.asarray(SCALE, dtype=np.float32)
    out, at = [], 0
    for rows, offsets in CLIPS:
        for o in offsets:
            out.append(emb[at + o:at + o + 16].reshape(-1))
        at += rows
    return np.stack(out)
